import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"四叉树与八叉树","description":"","frontmatter":{"title":"四叉树与八叉树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quadtree-octree.md","filePath":"cs/quadtree-octree.md","lastUpdated":1789023840000}'),h={name:"cs/quadtree-octree.md"};function u(_,a,m,f,A,B){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="四叉树与八叉树" tabindex="-1">四叉树与八叉树 <a class="header-anchor" href="#四叉树与八叉树" aria-label="Permalink to &quot;四叉树与八叉树&quot;">​</a></h1><div class="epigraph"><p>正方形一分为四、立方体一分为八；空块不再切。分辨率跟物体走，不跟数据页扇出走。</p><footer>—— 据 Finkel and Bentley, Quad Trees: A Data Structure for Retrieval on Composite Keys, Acta Informatica 1974；Samet, Foundations of Multidimensional and Metric Data Structures 整理</footer></div><p><a href="/cs/r-tree">上一课</a> 的 MBR 自适应且可重叠。<a href="/cs/kd-tree">k-d 树</a> 按数据中位数切。若域是固定包围盒、物体是图像像素或体素，用规则分裂更简单。本课不写页分裂启发式。缺口是四叉树 / 八叉树：几何中点切，到容量或深度停止。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平面区域或点集，反复把方块分成四象限，块内点少于阈值或到达最大深度则成叶。八叉树对立方体八分，用于三维场景、体素。查询：与询问区相交的块才下钻。缺口是<strong>规则四/八分</strong>，编码可用象限位，邻接查找有经典算法（Samet）。</p><p><span class="marginnote">Finkel and Bentley 1974。点四叉树与区域四叉树（黑白像素合并）是两种合同，本课都点名：前者叶存点，后者叶存均质块。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入点：从根走到含该点的叶，溢出则分裂再插。删除可能合并兄弟（若都变稀）。范围查询与 k-d 类似剪不相交方块。最近邻可优先探近的象限。</p>',8)),(e(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQ%5B%22%E6%AD%A3%E6%96%B9%E5%BD%A2%22%5D%20--%3E%20Q0%5B%22%E8%B1%A1%E9%99%90%2000%22%5D%0A%20%20SQ%20--%3E%20Q1%5B%22%E8%B1%A1%E9%99%90%2001%22%5D%0A%20%20SQ%20--%3E%20Q2%5B%22%E8%B1%A1%E9%99%90%2010%22%5D%0A%20%20SQ%20--%3E%20Q3%5B%22%E8%B1%A1%E9%99%90%2011%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 R 树：无 MBR 重叠问题，但空区域仍占树路径，偏斜数据会不平衡。与网格：四叉树是自适应分辨率网格。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>深度 \\(O(\\log(1/\\varepsilon))\\) 于最小特征尺寸，不是 \\(O(\\log n)\\)。最坏一条链（点挤在角上反复切）。三维八叉同构，只是扇出 8。本课不把 GPU 层次包围盒（BVH）写完，只承认同族。</p><p>空间填充曲线把四叉块序线性化，便于外存与缓存——下一课专门收 Hilbert / Morton。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写压缩四叉树的全部指针消除。高维 \\(2^k\\) 叉爆炸，勿把八叉推广到 20 维。字符串与后缀不是空间树。</p><p>后课默认：规则空间层次用四叉/八叉。要把块序变成一维局部性，用空间填充曲线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四叉/八叉：规则中点分裂，叶达容量或深度。</li><li>平衡不保证；偏斜退化。</li><li>下一课用曲线把多维块排成一维。</li><li>出处：Finkel and Bentley, 1974；Samet 的多维结构综述与专著。</li></ul>',9))])}const k=i(h,[["render",u]]);export{E as __pageData,k as default};
